    try {
        var savedEng = localStorage.getItem(ENGINE_STORAGE_KEY) || localStorage.getItem("_lightspeedfiltersixl_engine") || localStorage.getItem("_younus_engine");
        if (savedEng && ENGINES[savedEng]) currentEngine = savedEng;
    } catch (e) {}

    var omniEngine = document.getElementById("omni-engine");
    var pillBtns = document.querySelectorAll(".engine-pill");

    function extractSearchQueryFromUrl(urlStr) {
        if (!urlStr) return "";
        try {
            var u = new URL(urlStr);
            var h = u.hostname.toLowerCase();
            if (h.indexOf("google.") !== -1 || h.indexOf("bing.com") !== -1 || h.indexOf("duckduckgo.com") !== -1 || h.indexOf("search.brave.com") !== -1 || h.indexOf("ecosia.org") !== -1) {
                return u.searchParams.get("q") || "";
            }
            if (h.indexOf("search.yahoo.com") !== -1) {
                return u.searchParams.get("p") || "";
            }
        } catch (e) {}
        return "";
    }

    function setSearchEngine(eng, triggerActiveSearch) {
        if (!ENGINES[eng]) return;
        currentEngine = eng;
        try { localStorage.setItem(ENGINE_STORAGE_KEY, eng); } catch (e) {}
        if (omniEngine.value !== eng) omniEngine.value = eng;
        for (var i = 0; i < pillBtns.length; i++) {
            var b = pillBtns[i];
            if (b.getAttribute("data-engine") === eng) {
                b.classList.add("active");
            } else {
                b.classList.remove("active");
            }
        }
        if (triggerActiveSearch && !isHomeVisible) {
            var activeQ = extractSearchQueryFromUrl(currentProxiedUrl) || lastSearchQuery;
            if (activeQ) {
                navigate(ENGINES[eng].searchUrl(activeQ));
            }
        }
    }

    omniEngine.addEventListener("change", function() {
        setSearchEngine(omniEngine.value, true);
    });

    for (var i = 0; i < pillBtns.length; i++) {
        pillBtns[i].addEventListener("click", function() {
            setSearchEngine(this.getAttribute("data-engine"), false);
        });
    }
    setSearchEngine(currentEngine, false);

