    var CATEGORIES = ["All", "Social", "Video", "Gaming", "AI & Cloud", "Education", "Developer", "News & Sports", "Music", "Utilities & Life"];
    var activeCategory = "All";
    var filterQuery = "";

    var categoryTabsEl = document.getElementById("category-tabs");
    var siteGridEl = document.getElementById("site-grid");
    var siteFilterEl = document.getElementById("site-filter");

    // Precompute hostnames once to avoid creating URL objects on every filter keystroke
    for (var pIdx = 0; pIdx < WEBSITE_DIRECTORY.length; pIdx++) {
        var item = WEBSITE_DIRECTORY[pIdx];
        try {
            item.host = new URL(item.url).hostname.replace(/^www\./i, "");
        } catch (e) {
            item.host = item.url;
        }
        item.searchText = (item.name + " " + item.host + " " + item.cat).toLowerCase();
    }

    function renderCategoryTabs() {
        categoryTabsEl.textContent = "";
        var frag = document.createDocumentFragment();
        for (var i = 0; i < CATEGORIES.length; i++) {
            var cat = CATEGORIES[i];
            var count = 0;
            if (cat === "All") {
                count = WEBSITE_DIRECTORY.length;
            } else {
                for (var j = 0; j < WEBSITE_DIRECTORY.length; j++) {
                    if (WEBSITE_DIRECTORY[j].cat === cat) count++;
                }
            }
            var btn = document.createElement("button");
            btn.type = "button";
            btn.className = "cat-tab" + (activeCategory === cat ? " active" : "");
            btn.setAttribute("data-cat", cat);
            btn.textContent = cat + " (" + count + ")";
            frag.appendChild(btn);
        }
        categoryTabsEl.appendChild(frag);
    }

    // Event delegation on categoryTabsEl & siteGridEl (zero per-card event listeners -> saves Chromebook memory!)
    categoryTabsEl.addEventListener("click", function(ev) {
        var btn = ev.target && ev.target.closest ? ev.target.closest(".cat-tab") : null;
        if (!btn) return;
        activeCategory = btn.getAttribute("data-cat") || "All";
        renderCategoryTabs();
        renderSiteGrid();
    });

    siteGridEl.addEventListener("click", function(ev) {
        var card = ev.target && ev.target.closest ? ev.target.closest(".site-card") : null;
        if (!card) return;
        ev.preventDefault();
        var targetUrl = card.getAttribute("data-site-url");
        if (targetUrl) navigate(targetUrl);
    });

    function renderSiteGrid() {
        siteGridEl.textContent = "";
        var frag = document.createDocumentFragment();
        var q = filterQuery.toLowerCase();
        for (var i = 0; i < WEBSITE_DIRECTORY.length; i++) {
            var site = WEBSITE_DIRECTORY[i];
            if (activeCategory !== "All" && site.cat !== activeCategory) continue;
            if (q && site.searchText.indexOf(q) === -1) continue;

            var card = document.createElement("a");
            card.href = site.url;
            card.className = "site-card";
            card.setAttribute("data-site-url", site.url);
            card.setAttribute("data-site-name", site.name);
            var iconEl = document.createElement("div");
            iconEl.className = "site-icon";
            iconEl.textContent = site.badge;
            var infoEl = document.createElement("div");
            infoEl.className = "site-info";
            var nameEl = document.createElement("div");
            nameEl.className = "site-name";
            nameEl.textContent = site.name;
            var domEl = document.createElement("div");
            domEl.className = "site-domain";
            domEl.textContent = site.host;
            infoEl.appendChild(nameEl);
            infoEl.appendChild(domEl);
            card.appendChild(iconEl);
            card.appendChild(infoEl);
            frag.appendChild(card);
        }
        siteGridEl.appendChild(frag);
    }

    var filterRaf = 0;
    siteFilterEl.addEventListener("input", function() {
        filterQuery = (siteFilterEl.value || "").trim();
        if (filterRaf) cancelAnimationFrame(filterRaf);
        filterRaf = requestAnimationFrame(renderSiteGrid);
    });

    renderCategoryTabs();
    renderSiteGrid();

    // =========================================================================
    // 5. REAL SCRAMJET ENGINE + FAST US WISP BOOTSTRAP
    // =========================================================================
    var ASSETS_BASE = new URL("./", location.href).href;
    var BACKUP_ASSETS_BASE = "https://cdn.jsdelivr.net/gh/TongSherbet/storage@main/";

    function getAsset(path) {
        return ASSETS_BASE + String(path).replace(/^\//, "");
    }

    function getBackupAsset(path) {
        return BACKUP_ASSETS_BASE + String(path).replace(/^\//, "");
    }

    function loadScript(src, fallbackSrc) {
        return new Promise(function(resolve, reject) {
            var s = document.createElement("script");
            s.src = src;
            s.onload = function() {
                s.remove();
                resolve(true);
            };
            s.onerror = function() {
                s.remove();
                if (fallbackSrc && fallbackSrc !== src) {
                    loadScript(fallbackSrc, null).then(resolve).catch(reject);
                } else {
                    reject(new Error("Failed to load script: " + src));
                }
            };
            (document.head || document.documentElement).appendChild(s);
        });
    }

    // Verified US-only Wisp servers (~50ms latency, zero India geo-blocks for TikTok)
    var WISP_ENDPOINTS = [
        "wss://cdn.slcbmooc.org/",
        "wss://cdn.goaplytexas.org/",
        "wss://cdn.kcchallengevbc.com/",
        "wss://cdn.northstreetumc.org/",
        "wss://cdn.topstargym.net/",
        "wss://cdn.clearfieldswimming.com/",
        "wss://athollcottage.com/connection/",
        "wss://kidsprepnest.org/vi/"
    ];

    function testWispServer(wsUrl) {
        return new Promise(function(resolve, reject) {
            var ws;
            try {
                ws = new WebSocket(wsUrl);
            } catch (e) {
                return reject(e);
            }
            ws.binaryType = "arraybuffer";
            var streamId = (Math.floor(Math.random() * 4294967294) + 1) >>> 0;
            var sentConnect = false;
            var done = false;
            var cleanup = function() {
                clearTimeout(timer);
                ws.onmessage = ws.onerror = ws.onclose = null;
                try { ws.close(); } catch (e) {}
            };
            var timer = setTimeout(function() {
                if (done) return;
                done = true;
                cleanup();
                reject(new Error("timeout"));
            }, 2400);
            ws.onerror = ws.onclose = function() {
                if (done) return;
                done = true;
                cleanup();
                reject(new Error("closed"));
            };
            ws.onmessage = function(ev) {
                if (done) return;
                if (!(ev.data instanceof ArrayBuffer) || ev.data.byteLength < 5) return;
                var dv = new DataView(ev.data);
                var pType = dv.getUint8(0);
                var sId = dv.getUint32(1, true);
                if (sentConnect) {
                    if (sId === streamId) {
                        done = true;
                        cleanup();
                        resolve(wsUrl);
                    }
                    return;
                }
                if (sId === 0) {
                    if (pType === 5) {
                        ws.send(new Uint8Array([5, 0, 0, 0, 0, 2, 1]));
                    } else if (pType === 3) {
                        var hostBytes = (new TextEncoder()).encode("127.0.0.1");
                        var pkt = new Uint8Array(8 + hostBytes.length);
                        pkt.set([1, 0, 0, 0, 0, 1, 69, 0], 0);
                        pkt.set(hostBytes, 8);
                        new DataView(pkt.buffer).setUint32(1, streamId, true);
                        sentConnect = true;
                        ws.send(pkt);
                    }
                }
            };
        });
    }

    async function findFastestWisp() {
        try {
            var winner = await Promise.any(WISP_ENDPOINTS.map(testWispServer));
            if (winner) return winner;
        } catch (e) {}
        return WISP_ENDPOINTS[0];
    }

    async function swAlive(reg) {
        for (var i = 0; i < 16; i++) {
            try {
                var ctrl = new AbortController();
                var t = setTimeout(function() { ctrl.abort(); }, 1500);
                var r = await fetch(new URL("__sw_alive", reg.scope), { cache: "no-store", signal: ctrl.signal });
                clearTimeout(t);
                if ((await r.text()) === "true") return true;
            } catch (e) {}
            await new Promise(function(res) { setTimeout(res, 80); });
        }
        return false;
    }

    var controller = null;
    var transport = null;
    var scramjetFrame = null;
    var scramjetReady = false;

    async function initTransportInstance(tr) {
        for (var i = 0; i < 600; i++) {
            try {
                return await tr.init();
            } catch (e) {
                if (String(e).indexOf("wasm not loaded") === -1) throw e;
            }
            await new Promise(function(r) { setTimeout(r, 10); });
        }
        throw new Error("Transport init timed out");
    }

    async function bootScramjet() {
        if (scramjetReady && controller && scramjetFrame) return true;
        if (!navigator.serviceWorker) {
            throw new Error("Service Workers are not supported in this context");
        }

        // 1. Load Scramjet Core, Controller API, and Utils in parallel after core
        await loadScript(getAsset("sj/jet.core.js"), getBackupAsset("sj/jet.core.js"));
        await Promise.all([
            loadScript(getAsset("sj/jet.api.js"), getBackupAsset("sj/jet.api.js")),
            loadScript(getAsset("sj/jet.utils.js"), getBackupAsset("sj/jet.utils.js"))
        ]);

        // 2. Register Service Worker in current repo scope AND start Wisp discovery in parallel
        var wispPromise = findFastestWisp();
        var reg = await navigator.serviceWorker.register(getAsset("sw.js"), {
            scope: new URL("./", location.href).pathname,
            updateViaCache: "none"
        });

        if (!navigator.serviceWorker.controller) {
            var ctrlChanged = new Promise(function(resolve) {
                navigator.serviceWorker.addEventListener("controllerchange", resolve, { once: true });
            });
            var swTarget = reg.active || reg.waiting || reg.installing;
            if (swTarget) {
                try { swTarget.postMessage({ type: "OPM:claim" }); } catch (e) {}
                swTarget.addEventListener("statechange", function() {
                    if (swTarget.state === "activated" && reg.active) {
                        try { reg.active.postMessage({ type: "OPM:claim" }); } catch (e) {}
                    }
                });
            }
            await Promise.race([
                ctrlChanged,
                new Promise(function(r) { setTimeout(r, 5000); })
            ]);
        }

        if (!navigator.serviceWorker.controller && reg.active) {
            try { reg.active.postMessage({ type: "OPM:claim" }); } catch (e) {}
        }

        await swAlive(reg);

        // 3. Initialize Libcurl Wisp Transport
        var wispUrl = await wispPromise;
        var TransportCls = null;
        try {
            var mod = await import(getAsset("curl/index.mjs"));
            TransportCls = mod.default || mod.LibcurlClient || mod;
        } catch (e) {
            var mod2 = await import(getBackupAsset("curl/index.mjs"));
            TransportCls = mod2.default || mod2.LibcurlClient || mod2;
        }
        transport = new TransportCls({ wisp: wispUrl });
        await initTransportInstance(transport);

        // 4. Initialize Scramjet Controller
        var activeSw = navigator.serviceWorker.controller || reg.active;
        var readyResolveHook = null;
        var handshakeDone = new Promise(function(r) { readyResolveHook = r; });

        controller = new $jetController.Controller({
            serviceworker: activeSw,
            transport: transport,
            jetConfig: {
                maskedfiles: ["jet.inject.js", "jet.wasm.js"],
                flags: {
                    syncxhr: false,
                    disableComputedWrap: false,
                    rewriterLogs: false,
                    captureErrors: false,
                    cleanErrors: false,
                    scramitize: false,
                    sourcemaps: false,
                    destructureRewrites: true,
                    allowInvalidJs: true,
                    debugTrampolines: false,
                    debugSourceURL: false,
                    allowFailedIntercepts: true,
                    encapsulateWorkers: true
                }
            },
            config: {
                jetPath: getAsset("sj/jet.core.js"),
                wasmPath: getAsset("sj/jet.wasm"),
                injectPath: getAsset("sj/jet.inject.js"),
                virtualWasmPath: "jet.wasm.js",
                codec: {
                    encode: function(urlStr) {
                        if (!urlStr) return urlStr;
                        var key = globalThis.__jck;
                        if (key === undefined) {
                            key = [
                                location.origin.replace(/^\w+:\/\/|:\d+$/g, ""),
                                (new Date()).getUTCMonth(),
                                navigator.hardwareConcurrency,
                                navigator.deviceMemory,
                                navigator.platform,
                                navigator.userAgent.replace(/[\d.]+/g, ""),
                                (new Date()).getTimezoneOffset()
                            ].join().split("").reduce(function(a, b) {
                                return Math.imul(a ^ b.charCodeAt(0), 16777619);
                            }, 2166136261);
                            Object.defineProperty(globalThis, "__jck", { value: key });
                        }
                        var t = key;
                        var isHttps = urlStr.startsWith("https://") && urlStr.length > 8;
                        var bytes = (new TextEncoder()).encode(isHttps ? urlStr.slice(8) : urlStr);
                        for (var idx = 0, mask = 0; idx < bytes.length; idx++, mask >>>= 8) {
                            if ((idx & 3) === 0) {
                                t ^= t << 13;
                                t ^= t >>> 17;
                                t ^= t << 5;
                                mask = t;
                            }
                            bytes[idx] ^= mask;
                        }
                        var bin = "";
                        for (var k = 0; k < bytes.length; k += 8192) {
                            bin += String.fromCharCode.apply(null, bytes.subarray(k, k + 8192));
                        }
                        return (isHttps ? "" : "Z0") + btoa(bin).slice(0, ((4 * bytes.length + 2) / 3) | 0).replace(/Z/g, "Zz").replace(/\+/g, "Zp").replace(/\//g, "Zs");
                    },
                    decode: function(encStr) {
                        if (!encStr) return encStr;
                        var key = globalThis.__jck;
                        if (key === undefined) {
                            key = [
                                location.origin.replace(/^\w+:\/\/|:\d+$/g, ""),
                                (new Date()).getUTCMonth(),
                                navigator.hardwareConcurrency,
                                navigator.deviceMemory,
                                navigator.platform,
                                navigator.userAgent.replace(/[\d.]+/g, ""),
                                (new Date()).getTimezoneOffset()
                            ].join().split("").reduce(function(a, b) {
                                return Math.imul(a ^ b.charCodeAt(0), 16777619);
                            }, 2166136261);
                            Object.defineProperty(globalThis, "__jck", { value: key });
                        }
                        var t = key;
                        var isNonHttps = encStr.startsWith("Z0");
                        var raw = atob(encStr.slice(isNonHttps ? 2 : 0).replace(/Zp/g, "+").replace(/Zs/g, "/").replace(/Zz/g, "Z"));
                        var out = new Uint8Array(raw.length);
                        for (var idx = 0, mask = 0; idx < out.length; idx++, mask >>>= 8) {
                            if ((idx & 3) === 0) {
                                t ^= t << 13;
                                t ^= t >>> 17;
                                t ^= t << 5;
                                mask = t;
                            }
                            out[idx] = raw.charCodeAt(idx) ^ mask;
                        }
                        return (isNonHttps ? "" : "https://") + (new TextDecoder("utf-8", { ignoreBOM: true })).decode(out);
                    }
                },
                prefix: new URL("./~/", location.href).pathname
            }
        });

        var origReadyResolve = controller.readyResolve;
        controller.readyResolve = function() {
            readyResolveHook(true);
            return origReadyResolve.apply(controller, arguments);
        };

        navigator.serviceWorker.addEventListener("controllerchange", function() {
            if (navigator.serviceWorker.controller && controller) {
                controller.serviceWorkerController = navigator.serviceWorker.controller;
                controller.setupMessagePort();
            }
        });

        for (var attempt = 0; !(await Promise.race([handshakeDone, new Promise(function(r) { setTimeout(function() { r(false); }, 3500); })])); attempt++) {
            if (attempt >= 4) break;
            controller.serviceWorkerController = navigator.serviceWorker.controller || controller.serviceWorkerController;
            controller.setupMessagePort();
        }

        await controller.wait();
        controller.guardServiceWorkerRevive = false;

        // Clean up RPC tokens on pagehide to prevent memory leaks on Chromebooks
        window.addEventListener("pagehide", function() {
            try {
                if (controller && controller.rpc && controller.rpc.tokens) {
                    for (var tk of Object.keys(controller.rpc.tokens)) {
                        clearInterval(controller.rpc.tokens[tk]);
                        delete controller.rpc.tokens[tk];
                    }
                }
            } catch (e) {}
        }, { once: true });

        // Lightweight Service Worker health check (paused when tab is hidden to save Chromebook battery/CPU)
        setInterval(async function() {
            if (document.hidden) return;
            try {
                var r = await navigator.serviceWorker.getRegistration(new URL("./", location.href).pathname);
                if (!r) {
                    await navigator.serviceWorker.register(getAsset("sw.js"), {
                        scope: new URL("./", location.href).pathname,
                        updateViaCache: "none"
                    });
                }
                if (controller && navigator.serviceWorker.controller && controller.serviceWorkerController !== navigator.serviceWorker.controller) {
                    controller.serviceWorkerController = navigator.serviceWorker.controller;
                    controller.setupMessagePort();
                }
            } catch (e) {}
        }, 45000);

        // 5. Create Scramjet Frame with AdBlocker & URL Watcher Plugins
        var webFrameEl = document.getElementById("web-frame");
        var plugins = [
            new $jetUtils.HttpCachePlugin(),
            new $jetUtils.UrlWatcherPlugin(function(newUrl) {
                onProxiedUrlChange(newUrl);
            })
        ];

        try {
            var LightspeedPlugin = class extends $jetController.ManagedPlugin {
                constructor() {
                    super("lightspeed-guard", []);
                }
                install(ctx) {
                    this.tap(ctx.hooks.init.post, function(ev) {
                        if (ev && ev.window) {
                            injectClientAdBlocker(ev.window);
                        }
                    });
                }
            };
            plugins.push(new LightspeedPlugin());
        } catch (e) {}

        scramjetFrame = controller.createFrame(webFrameEl, { plugins: plugins });
        scramjetFrame.prefix = controller.prefix;
        scramjetFrame.fetchHandler.context = scramjetFrame.context;
        scramjetFrame.fetchHandler.context.hooks = { rewriter: scramjetFrame.fetchHandler.hooks.rewriter };

        webFrameEl.addEventListener("load", function() {
            hideLoading();
            try {
                if (webFrameEl.contentWindow) {
                    injectClientAdBlocker(webFrameEl.contentWindow);
                }
            } catch (e) {}
            updateNavButtons();
        });

        scramjetReady = true;
        return true;
    }

    // Start Scramjet boot immediately in background while user is on Entry/Password screen
    var scramjetBootPromise = bootScramjet().catch(function(err) {
        console.error("Scramjet init error:", err);
        return false;
    });

    // =========================================================================
    // 6. NAVIGATION, URL ROUTER & HISTORY CONTROLS
    // =========================================================================
    var homeView = document.getElementById("home-view");
    var frameWrap = document.getElementById("frame-wrap");
    var webFrame = document.getElementById("web-frame");
    var loadingOverlay = document.getElementById("loading-overlay");
    var loadingText = document.getElementById("loading-text");
    var omniInput = document.getElementById("omni-input");
    var btnBack = document.getElementById("btn-back");
    var btnFwd = document.getElementById("btn-fwd");
    var btnReload = document.getElementById("btn-reload");
    var btnHome = document.getElementById("btn-home");

    var HOME_TOKEN = "lightspeed://home";
    var isHomeVisible = true;
    var currentProxiedUrl = "";
    var lastSearchQuery = "";
    var historyList = [HOME_TOKEN];
    var historyIdx = 0;
    var isTraversing = false;

    function showLoading(msg) {
        loadingText.textContent = msg || "Loading...";
        loadingOverlay.style.display = "flex";
    }

    function hideLoading() {
        loadingOverlay.style.display = "none";
    }

    function pauseFrameMedia() {
        try {
            var doc = webFrame.contentDocument;
            if (!doc) return;
            var mediaEls = doc.querySelectorAll("video, audio");
            for (var i = 0; i < mediaEls.length; i++) {
                try { mediaEls[i].pause(); } catch (e) {}
            }
        } catch (e) {}
    }

    function canFrameStep(dir) {
        try {
            var nav = webFrame.contentWindow && webFrame.contentWindow.navigation;
            if (nav && typeof nav.canGoBack === "boolean") {
                return dir < 0 ? nav.canGoBack : nav.canGoForward;
            }
        } catch (e) {}
        return false;
    }

    function updateNavButtons() {
        if (isHomeVisible) {
            btnBack.disabled = historyIdx <= 0;
            btnFwd.disabled = historyIdx >= historyList.length - 1;
        } else {
            btnBack.disabled = !(historyIdx > 0 || canFrameStep(-1));
            btnFwd.disabled = !(historyIdx < historyList.length - 1 || canFrameStep(1));
        }
    }

    function onProxiedUrlChange(url) {
        if (!url || !/^https?:\/\//i.test(url)) return;
        if (/google\.[^/]+\/sorry\//i.test(url)) {
            var q = lastSearchQuery;
            try {
                var uObj = new URL(url);
                var cont = uObj.searchParams.get("continue");
                if (cont) {
                    var cObj = new URL(cont);
                    if (cObj.searchParams.get("q")) q = cObj.searchParams.get("q");
                }
            } catch (e) {}
            if (q && scramjetFrame) {
                scramjetFrame.go("https://www.bing.com/search?q=" + encodeURIComponent(q));
            }
            return;
        }
        hideLoading();
        if (url !== currentProxiedUrl) {
            currentProxiedUrl = url;
            omniInput.value = url;
            var detectedQ = extractSearchQueryFromUrl(url);
            if (detectedQ) lastSearchQuery = detectedQ;
            if (!isTraversing) {
                if (historyList[historyIdx] !== url) {
                    historyList = historyList.slice(0, historyIdx + 1);
                    historyList.push(url);
                    historyIdx = historyList.length - 1;
                }
            }
            isTraversing = false;
            updateNavButtons();
        }
    }

    function showHome(pushToHist) {
        hideLoading();
        pauseFrameMedia();
        isHomeVisible = true;
        currentProxiedUrl = "";
        omniInput.value = "";
        frameWrap.style.display = "none";
        homeView.style.display = "flex";
        if (pushToHist && historyList[historyIdx] !== HOME_TOKEN) {
            historyList = historyList.slice(0, historyIdx + 1);
            historyList.push(HOME_TOKEN);
            historyIdx = historyList.length - 1;
        }
        updateNavButtons();
    }

    var QUICK_SHORTCUTS = {
        "tiktok": "https://www.tiktok.com/foryou",
        "tiktok.com": "https://www.tiktok.com/foryou",
        "www.tiktok.com": "https://www.tiktok.com/foryou",
        "x": "https://x.com/",
        "twitter": "https://x.com/"
    };
    for (var sIdx = 0; sIdx < WEBSITE_DIRECTORY.length; sIdx++) {
        var entry = WEBSITE_DIRECTORY[sIdx];
        var keyName = entry.name.toLowerCase();
        if (!QUICK_SHORTCUTS[keyName]) {
            QUICK_SHORTCUTS[keyName] = entry.url;
        }
    }

    function resolveInputToUrl(raw) {
        var s = String(raw || "").trim();
        if (!s) return "";
        var low = s.toLowerCase();
        if (QUICK_SHORTCUTS[low]) return QUICK_SHORTCUTS[low];
        if (/^@[a-z0-9._-]+$/i.test(s)) {
            return "https://www.tiktok.com/" + s;
        }
        if (/^(?:tt|tiktok)\s+@?([a-z0-9._-]+)$/i.test(s)) {
            var match = s.match(/^(?:tt|tiktok)\s+@?([a-z0-9._-]+)$/i);
            return "https://www.tiktok.com/@" + match[1];
        }
        if (/^https?:\/\//i.test(s)) {
            try {
                var parsed = new URL(s);
                var h = parsed.hostname.replace(/^www\./i, "").toLowerCase();
                if (h === "tiktok.com" && (parsed.pathname === "/" || parsed.pathname === "")) {
                    return "https://www.tiktok.com/foryou";
                }
            } catch (e) {}
            return s;
        }
        if (s.indexOf(" ") === -1 && /^[a-z0-9-]+(\.[a-z0-9-]+)+(\/.*)?$/i.test(s)) {
            return resolveInputToUrl("https://" + s);
        }
        lastSearchQuery = s;
        return ENGINES[currentEngine].searchUrl(s);
    }

    async function navigate(rawInput, opts) {
        opts = opts || {};
        var targetUrl = resolveInputToUrl(rawInput);
        if (!targetUrl || isAdUrl(targetUrl)) return;

        pauseFrameMedia();
        isHomeVisible = false;
        currentProxiedUrl = targetUrl;
        omniInput.value = targetUrl;
        var qInTarget = extractSearchQueryFromUrl(targetUrl);
        if (qInTarget) lastSearchQuery = qInTarget;
        homeView.style.display = "none";
        frameWrap.style.display = "block";

        if (!opts.fromHistory) {
            if (historyList[historyIdx] !== targetUrl) {
                historyList = historyList.slice(0, historyIdx + 1);
                historyList.push(targetUrl);
                historyIdx = historyList.length - 1;
            }
        }
        updateNavButtons();

        var hostLabel = targetUrl;
        try { hostLabel = new URL(targetUrl).hostname; } catch (e) {}
        showLoading("Loading " + hostLabel + "...");

        var ok = await scramjetBootPromise;
        if (!ok || !scramjetReady || !scramjetFrame) {
            scramjetBootPromise = bootScramjet().catch(function() { return false; });
            ok = await scramjetBootPromise;
        }

        if (ok && scramjetFrame) {
            try {
                scramjetFrame.go(targetUrl);
                setTimeout(hideLoading, 4500);
                return;
            } catch (e) {
                console.error("scramjetFrame.go error:", e);
            }
        }

        hideLoading();
        webFrame.src = targetUrl;
    }

    btnHome.addEventListener("click", function() {
        showHome(true);
    });

    btnBack.addEventListener("click", function() {
        if (!isHomeVisible && scramjetFrame && canFrameStep(-1)) {
            isTraversing = true;
            try { scramjetFrame.back(); return; } catch (e) {}
        }
        if (historyIdx > 0) {
            historyIdx -= 1;
            var target = historyList[historyIdx];
            if (target === HOME_TOKEN) {
                showHome(false);
            } else {
                isTraversing = true;
                navigate(target, { fromHistory: true });
            }
        }
    });

    btnFwd.addEventListener("click", function() {
        if (!isHomeVisible && scramjetFrame && canFrameStep(1)) {
            isTraversing = true;
            try { scramjetFrame.forward(); return; } catch (e) {}
        }
        if (historyIdx < historyList.length - 1) {
            historyIdx += 1;
            var target = historyList[historyIdx];
            if (target === HOME_TOKEN) {
                showHome(false);
            } else {
                isTraversing = true;
                navigate(target, { fromHistory: true });
            }
        }
    });

    btnReload.addEventListener("click", function() {
        if (isHomeVisible) return;
        if (scramjetFrame) {
            showLoading("Reloading...");
            try {
                scramjetFrame.reload();
                setTimeout(hideLoading, 4000);
                return;
            } catch (e) {}
        }
        if (currentProxiedUrl) {
            navigate(currentProxiedUrl, { fromHistory: true });
        }
    });

    document.getElementById("omni-form").addEventListener("submit", function(e) {
        e.preventDefault();
        var v = omniInput.value.trim();
        if (v) navigate(v);
    });

    document.getElementById("home-form").addEventListener("submit", function(e) {
        e.preventDefault();
        var hi = document.getElementById("home-input");
        var v = hi.value.trim();
        if (v) navigate(v);
    });

    window.addEventListener("keydown", function(e) {
        if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
            e.preventDefault();
            if (isHomeVisible) {
                document.getElementById("home-input").focus();
            } else {
                omniInput.focus();
                omniInput.select();
            }
        }
    });

})();
